575	// RemoveInstalledPlugin removes every managed-dir entry whose bare name
576	// matches name. Symlinks are unlinked without touching the source file.
577	//
578	// Iterating all variants matters on Windows, where entire-foo.exe,
579	// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
580	// otherwise leave a runnable variant behind after `entire plugin remove foo`.
581	// On Unix the loop typically runs once.
582	func RemoveInstalledPlugin(name string) error {
583		variants, err := installedVariantsByBareName(name)
584		if err != nil {
585			return err
586		}
587		if len(variants) == 0 {
588			return fmt.Errorf("plugin %q is not installed in the managed directory", name)
589		}
590		root, err := pluginRoot(false)
591		if err != nil {
592			return err
593		}
594		for _, p := range variants {
595			// Remove by name inside the managed tree, not by the absolute path
596			// listing handed back: the whole point is that an entry name can never
597			// address a file outside the tree, however it was produced.
598			if err := root.Remove(pluginBinName(filepath.Base(p.Path))); err != nil && !errors.Is(err, os.ErrNotExist) {
599				return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
600			}
601		}
602		return nil
603	}
