110	// PluginDataDir returns the per-plugin data directory for the given bare name
111	// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
112	// the plugin's responsibility on first use.
113	//
114	// Returns an error for names the dispatcher would never invoke (empty,
115	// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
116	// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
117	// data subtree.
118	func PluginDataDir(name string) (string, error) {
119		if err := validatePluginName(name); err != nil {
120			return "", err
121		}
122		parent, err := pluginParentDir()
123		if err != nil {
124			return "", err
125		}
126		return filepath.Join(parent, pluginManagedDataSubdir, name), nil
