175	// pluginRoot returns the shared *os.Root over the managed plugin directory —
176	// the parent of bin/, pkg/, and data/ — creating it when create is set.
177	//
178	// Every read, write, rename, symlink and removal Entire performs inside the
179	// managed tree resolves as a name in this root. Plugin names are validated by
180	// validatePluginName before they reach a path today, and PluginDataDir carries a
181	// comment saying that validation is what "guarantees ENTIRE_PLUGIN_DATA_DIR
182	// always points inside the managed data subtree". The root is what keeps that
183	// guarantee when the validation changes, or when a name arrives by a route that
184	// does not go through it: this tree is populated from a remote index and remote
185	// archives, so it is the last place a name should be trusted on its shape alone.
186	func pluginRoot(create bool) (*os.Root, error) {
187		parent, err := pluginParentDir()
