220	// PrependPluginBinDirToPATH prepends the managed bin dir to the process's
221	// PATH so the kubectl dispatcher discovers managed-installed plugins.
222	// Idempotent against an already-prepended dir.
223	//
224	// Returns a restore closure the caller invokes to revert PATH to its
225	// previous value. Restoring matters when no plugin runs: built-in commands
226	// and the subprocesses they spawn (git, hooks, less, …) should see the
227	// user's original PATH, not one with the managed plugin dir prepended.
228	// When a plugin *is* dispatched, callers can simply skip the restore — the
229	// process exits anyway, and the plugin child intentionally inherits the
230	// prepended PATH so it can spawn sibling managed plugins.
231	//
232	// Errors and no-op cases (already-prepended, lookup failure) return a
233	// no-op restore so callers always have a safe func to call. Failures are
234	// emitted at debug level — the surface symptom ("my managed plugin
235	// doesn't run") is otherwise silent and hard to diagnose; a debug log
236	// surfaces the cause for users who flip log_level=DEBUG.
237	func PrependPluginBinDirToPATH(ctx context.Context) func() {
238		dir, err := PluginBinDir()
239		if err != nil || dir == "" {
240			if err != nil {
241				logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: resolve failed", slog.String("error", err.Error()))
242			}
243			return func() {}
244		}
245		prev := os.Getenv("PATH")
246		sep := string(os.PathListSeparator)
247		if prev == "" {
248			if err := os.Setenv("PATH", dir); err != nil {
249				logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
250				return func() {}
251			}
252			return func() { _ = os.Setenv("PATH", "") }
253		}
254		// Idempotent: if the first entry already matches, leave PATH alone.
255		// Windows PATH lookups are case-insensitive (`C:\Foo` and `c:\foo`
256		// resolve identically), so a case-different first entry is the same
257		// dir and we should not double-prepend.
258		first := prev
259		if i := strings.Index(prev, sep); i >= 0 {
260			first = prev[:i]
261		}
262		if pathEntriesEqual(first, dir) {
263			return func() {}
264		}
265		if err := os.Setenv("PATH", dir+sep+prev); err != nil {
266			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
267			return func() {}
268		}
269		return func() { _ = os.Setenv("PATH", prev) }
270	}
