272	// pathEntriesEqual reports whether two PATH entries refer to the same dir.
273	// filepath.Clean normalizes trailing separators and (on Windows) slash
274	// orientation; case folding handles Windows' case-insensitive lookup.
275	func pathEntriesEqual(a, b string) bool {
276		a = filepath.Clean(a)
277		b = filepath.Clean(b)
278		if runtime.GOOS == windowsGOOS {
279			return strings.EqualFold(a, b)
280		}
281		return a == b
282	}
