246	func rootSymlink(r *Root, oldname, newname string) error {
247		if oldname == "" {
248			return syscall.EINVAL
249		}
250	
251		// Windows treats / and \ as equivalent almost everywhere, but not in symlink targets.
252		// Match os.Symlink behavior and convert / to \.
253		oldname = filepathlite.FromSlash(oldname)
254	
255		// CreateSymbolicLinkW converts volume-relative paths into absolute ones.
256		// Do the same.
257		if filepathlite.VolumeNameLen(oldname) > 0 && !filepathlite.IsAbs(oldname) {
258			p, err := syscall.FullPath(oldname)
259			if err == nil {
260				oldname = p
261			}
262		}
263	
264		// If oldname can be resolved to a directory in the root, create a directory link.
265		// Otherwise, create a file link.
266		var flags windows.SymlinkatFlags
267		if filepathlite.VolumeNameLen(oldname) == 0 && !IsPathSeparator(oldname[0]) {
268			// oldname is a path relative to the directory containing newname.
269			// Prepend newname's directory to it to make a path relative to the root.
270			// For example, if oldname=old and newname=a\new, destPath=a\old.
271			destPath := oldname
272			if dir := dirname(newname); dir != "." {
273				destPath = dir + `\` + oldname
274			}
275			fi, err := r.Stat(destPath)
276			if err == nil && fi.IsDir() {
277				flags |= windows.SYMLINKAT_DIRECTORY
278			}
279		}
280	
281		// Empirically, CreateSymbolicLinkW appears to set the relative flag iff
282		// the target does not contain a volume name.
283		if filepathlite.VolumeNameLen(oldname) == 0 {
284			flags |= windows.SYMLINKAT_RELATIVE
285		}
286	
287		_, err := doInRoot(r, newname, 0, nil, func(parent sysfdType, name string, endsInSlash bool) (struct{}, error) {
288			return struct{}{}, windows.Symlinkat(oldname, parent, name, flags)
289		})
290		if err != nil {
291			return &LinkError{"symlinkat", oldname, newname, err}
292		}
293		return nil
294	}
