382	func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
383		if err := requireSecureAssetURL(rawURL); err != nil {
384			return nil, err
385		}
386		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
387		if err != nil {
388			return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
389		}
390		resp, err := pluginHTTPClient.Do(req)
391		if err != nil {
392			return nil, fmt.Errorf("GET %s: %w", redactURL(rawURL), err)
393		}
394		defer resp.Body.Close()
395		if resp.StatusCode != http.StatusOK {
396			return nil, fmt.Errorf("GET %s: %s", redactURL(rawURL), resp.Status)
397		}
398		// readWithinLimit, not a bare LimitReader: this fetches checksums.txt, and
399		// silently truncating it would drop the line covering our asset — turning a
400		// verifiable download into an "unverified" one for a reason nobody could see.
401		data, err := readWithinLimit(resp.Body, maxChecksumsSize)
