package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

func main() {
	dir, _ := os.MkdirTemp("", "symrepro-")
	defer os.RemoveAll(dir)
	os.MkdirAll(filepath.Join(dir, "pkg", "x"), 0o755)
	os.MkdirAll(filepath.Join(dir, "bin"), 0o755)
	// A real executable as the target: copy cmd.exe? use a tiny .bat via cmd is enough for Stat; for exec use powershell -c? Keep to Stat + Open.
	src := filepath.Join(dir, "pkg", "x", "entire-x.exe")
	os.WriteFile(src, []byte("MZ payload"), 0o644)
	root, err := os.OpenRoot(dir)
	if err != nil {
		panic(err)
	}
	defer root.Close()

	// 1. Root.Symlink with absolute target
	err = root.Symlink(src, "bin/root-abs")
	fmt.Println("root.Symlink(abs):", err)
	if err == nil {
		tgt, rerr := os.Readlink(filepath.Join(dir, "bin", "root-abs"))
		fmt.Println("  Readlink:", tgt, rerr)
		_, serr := os.Stat(filepath.Join(dir, "bin", "root-abs"))
		fmt.Println("  Stat through link:", serr)
		_, oerr := os.ReadFile(filepath.Join(dir, "bin", "root-abs"))
		fmt.Println("  ReadFile through link:", oerr)
	}
	// 2. os.Symlink with absolute target (control)
	err = os.Symlink(src, filepath.Join(dir, "bin", "os-abs"))
	fmt.Println("os.Symlink(abs):", err)
	if err == nil {
		_, serr := os.Stat(filepath.Join(dir, "bin", "os-abs"))
		fmt.Println("  Stat through link:", serr)
	}
	// 3. Root.Symlink with relative target
	err = root.Symlink(`..\pkg\x\entire-x.exe`, "bin/root-rel")
	fmt.Println("root.Symlink(rel):", err)
	if err == nil {
		_, serr := os.Stat(filepath.Join(dir, "bin", "root-rel"))
		fmt.Println("  Stat through link:", serr)
	}
	// 4. Root.Link with absolute oldname
	err = root.Link(src, "bin/link-abs")
	fmt.Println("root.Link(abs):", err)
	// 5. Root.Link with root-relative oldname
	err = root.Link("pkg/x/entire-x.exe", "bin/link-rel")
	fmt.Println("root.Link(rel):", err)
	if err == nil {
		a, _ := os.Stat(src)
		b, _ := os.Stat(filepath.Join(dir, "bin", "link-rel"))
		fmt.Println("  SameFile:", os.SameFile(a, b), "size:", b.Size())
	}
	// 6. exec through a Root.Symlink absolute link to a real exe
	real, _ := exec.LookPath("cmd.exe")
	err = root.Symlink(real, "bin/cmdlink.exe")
	fmt.Println("root.Symlink(abs cmd.exe):", err)
	if err == nil {
		out, xerr := exec.Command(filepath.Join(dir, "bin", "cmdlink.exe"), "/c", "echo hi").CombinedOutput()
		fmt.Printf("  exec through root link: out=%q err=%v\n", out, xerr)
	}
	err = os.Symlink(real, filepath.Join(dir, "bin", "cmdlink2.exe"))
	if err == nil {
		out, xerr := exec.Command(filepath.Join(dir, "bin", "cmdlink2.exe"), "/c", "echo hi").CombinedOutput()
		fmt.Printf("  exec through os link: out=%q err=%v\n", out, xerr)
	}
}
EOF
go run . 2>&1

